import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@DOC-04";
const TEN_MIB_PLUS_ONE = 10 * 1024 * 1024 + 1;

const cases = [
  {
    label: "an empty file",
    file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
    kind: "w9",
    status: 422,
    code: "empty_file",
  },
  {
    label: "a file of exactly 10 MiB + 1",
    file: {
      name: "too-large.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(TEN_MIB_PLUS_ONE, 0x61),
    },
    kind: "w9",
    status: 413,
    code: "file_too_large",
  },
  {
    label: 'a ".exe" file',
    file: {
      name: "setup.exe",
      mimeType: "application/x-msdownload",
      buffer: Buffer.from("MZ\x90\x00 not really a program"),
    },
    kind: "w9",
    status: 415,
    code: "unsupported_type",
  },
  {
    label: "a valid text file",
    file: {
      name: "notes.txt",
      mimeType: "text/plain",
      buffer: Buffer.from("Vendor onboarding notes"),
    },
    kind: "passport",
    status: 422,
    code: "validation_error",
  },
] as const;

test.describe("Upload vendor documents", () => {
  for (const c of cases) {
    test(
      `rejects ${c.label} as kind "${c.kind}" with ${c.status} ${c.code}`,
      { tag: TAG },
      async ({ apiAs }) => {
        // Arrange: a draft vendor owned by the member's tenant
        const member = await apiAs("member");
        const createResponse = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC-04 Vendor"),
            category: "services",
            contact_email: "billing@doc04.example.com",
          },
        });
        expect(createResponse.status()).toBe(201);
        const vendor = await createResponse.json();
        expect(vendor.status).toBe("draft");

        // Act: upload the invalid document
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: c.kind,
            file: c.file,
          },
        });

        // Assert
        expect(response.status()).toBe(c.status);
        const body = await response.json();
        expect(body.error.code).toBe(c.code);
      },
    );
  }
});
